dashboard.definition:
{
    "title": "Datacenter Facility",
    "description": "Datacenter facility: temperature per zone, power per circuit, cooling and UPS",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_base": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_infra location=\"$site$\" sensor_type IN (temperature, power, cooling, ups, humidity)\n| eval key=coalesce(zone, circuit, device_id, sensor_id)\n| eval v=case(sensor_type=\"temperature\", value_celsius, sensor_type=\"power\", value_kw, sensor_type=\"cooling\", supply_temp_celsius, sensor_type=\"ups\", battery_charge_pct, sensor_type=\"humidity\", value_pct)\n| bin _time span=5m\n| stats avg(v) as v max(v) as vmax avg(threshold_critical) as limit avg(pue) as pue avg(load_pct) as load avg(return_temp_celsius) as ret avg(fan_speed_pct) as fan avg(runtime_minutes) as runtime latest(status) as status by _time location sensor_type key",
                "enableSmartSources": true
            },
            "name": "Facility sensors (5 min)"
        },
        "ds_k_temp": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"temperature\" | timechart span=5m avg(v) as \"Average temperature\""
            }
        },
        "ds_k_power": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"power\" AND like(key, \"%-power-total\") | timechart span=5m sum(v) as \"Facility power\""
            }
        },
        "ds_k_pue": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"power\" AND like(key, \"%-power-total\") | timechart span=5m avg(pue) as PUE"
            }
        },
        "ds_k_ups": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"ups\" | timechart span=5m avg(v) as \"UPS battery\""
            }
        },
        "ds_k_hum": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"humidity\" | timechart span=5m avg(v) as Humidity"
            }
        },
        "ds_rings": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"temperature\"\n| stats avg(v) as value max(vmax) as peak by location\n| eval name=upper(substr(location, 1, 1)).substr(location, 2), value=round(value, 1), unit=\"°C\", min=15, max=30, warn=22, crit=25, better=\"lower\", key=location, detail=\"Hottest zone peak \".round(peak, 1).\" °C\"\n| table name value unit min max warn crit better detail key"
            }
        },
        "ds_heat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"temperature\" AND limit > 0\n| eval zone=location.\" · \".replace(key, \"_\", \" \"), pct=round(100 * vmax / limit, 0)\n| timechart span=5m limit=0 max(pct) by zone"
            }
        },
        "ds_power": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"power\" AND NOT like(key, \"%-power-total\") | timechart span=5m sum(v) by key"
            }
        },
        "ds_cooling": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"cooling\" | timechart span=5m avg(v) as \"Supply °C\" avg(ret) as \"Return °C\" avg(fan) as \"Fan %\""
            }
        },
        "ds_ups": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type=\"ups\" | timechart span=5m avg(v) as \"Battery %\" avg(load) as \"Load %\""
            }
        },
        "ds_sensors": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where sensor_type IN (\"temperature\", \"cooling\", \"ups\", \"humidity\")\n| stats latest(v) as current max(vmax) as peak latest(limit) as limit latest(status) as Status latest(runtime) as runtime by location sensor_type key\n| eval Current=round(current, 1), Peak=round(peak, 1), \"Critical at\"=round(limit, 0), \"UPS runtime min\"=round(runtime, 0)\n| table location sensor_type key Current Peak \"Critical at\" Status \"UPS runtime min\"\n| rename location as Site sensor_type as Type key as \"Zone or device\""
            }
        },
        "ds_events": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_infra location=\"$site$\" sensor_type IN (access_control, fire_suppression, leak_detection, environmental)\n| stats count as Events latest(status) as Status latest(_time) as last by location sensor_type\n| eval \"Last event\"=strftime(last, \"%H:%M:%S\"), Status=coalesce(Status, \"-\")\n| table location sensor_type Events Status \"Last event\"\n| rename location as Site sensor_type as System",
                "enableSmartSources": true
            },
            "name": "Facility safety systems"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
